static const uint8_t img_right[16] = {0x00, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0x90, 0x90,
                                       0x98, 0x94, 0x62, 0x01, 0x00, 0x00, 0x00, 0x00}; // R
static const uint8_t img_stop[16]  = {0x00, 0x00, 0x18, 0x18, 0x18, 0x18, 0x00, 0x00,
