    int idx = x + (y / 8) * 128;
    if (on) s_oled_fb[idx] |=  (1 << (y % 8));
    else    s_oled_fb[idx] &= ~(1 << (y % 8));
}

static void oled_print(int col, int row, const char *str, int on) {
    int x = col * 8;
    int y = row * 8;
    while (*str) {
        char c = *str++;
        if (c < 32 || c > 127) c = ' ';
        int fi = c - 32;
        for (int r = 0; r < 8; r++) {
            uint8_t line = font8x8[fi][r];
            for (int cl = 0; cl < 8; cl++) {
                if (line & (1 << (7 - cl))) oled_draw_pixel(x + cl, y + r, on);
            }
        }
        x += 8;
    }
}
